struct Complex
  property real : Float64
  property imag : Float64

  def *(other : Complex) : Complex
    # Komplex szorzás: (a+bi)*(c+di) = (ac-bd) + (ad+bc)i
    Complex.new(
      self.real * other.real - self.imag * other.imag,
      self.real * other.imag + self.imag * other.real
    )
  end

  def magnitude : Float64
    Math.sqrt(self.real**2 + self.imag**2)
  end

  def phase : Float64
    Math.atan2(self.imag, self.real)
  end
end

class CVKANLayer
  property spline_coeffs : Array(Array(Complex))
  property grid_size : Int32
  property input_dim : Int32
  property output_dim : Int32

  def initialize(@input_dim, @output_dim, @grid_size)
    # Komplex spline-együtthatók inicializálása
    # Polar formában: magnitude = uniform(0, 1), phase = uniform(0, 2π)
    @spline_coeffs = Array.new(@output_dim) do
      Array.new(@grid_size) do
        mag = Random.rand
        phase = Random.rand * 2.0 * Math::PI
        Complex.new(mag * Math.cos(phase), mag * Math.sin(phase))
      end
    end
  end

  def forward(input : Array(Complex)) : Array(Complex)
    # Komplex spline-interpoláció
    # Komplex B-spline bázis függvények
    # TELJES implementáció
    output = Array(Complex).new(@output_dim) { Complex.new(0.0, 0.0) }

    @output_dim.times do |i|
      input.each_with_index do |x, j|
        knots = (0...@grid_size).map { |k| k.to_f64 / (@grid_size - 1) }
        basis = complex_b_spline_basis(x, knots, 3)

        # Konvolúció komplex együtthatókkal
        eval = Complex.new(0.0, 0.0)
        basis.each_with_index do |b, k|
          eval = eval + (b * @spline_coeffs[i][k])
        end
        output[i] = output[i] + eval
      end
    end

    # Komplex ReLU: magnitude(z) > 0 ? z : 0
    output.map { |z| z.magnitude > 0.0 ? z : Complex.new(0.0, 0.0) }
